/* ---------- login ---------- */
function regOk(L){return L.fio.trim().split(/\s+/).length>=2&&/^\S+@\S+\.\S+$/.test(L.email)}
function resendText(L){return L.resend>0?'Повторно запросить код можно через 0:'+pad(L.resend):'Код можно запросить повторно'}
function loginBody(){
 var L=S.login,b;
 if(L.step==='start'){b='<h3>Вход в аккаунт</h3><p>Быстрее всего через Telegram: без кода и пароля, одним нажатием.</p><button class="btn tgbig" data-act="ltg">'+ic('send',20)+'Войти через Telegram</button><div class="or">или</div><button class="btn outline" data-act="lphone">По номеру телефона</button>'}
 else if(L.step==='tg'){b='<h3>Открываем Telegram…</h3><p>Подтвердите вход в приложении Telegram.</p><div class="wait"><span class="spin" aria-hidden="true"></span></div><button class="btn outline" data-act="lcancel">Отмена</button>'}
 else if(L.step==='phone'){b='<h3>Вход по номеру</h3><div class="fld"><label class="lbl2" for="lph">Номер телефона, привязанный к Telegram</label><div class="inp"><input id="lph" data-bind="lph" inputmode="tel" placeholder="+7 XXX XXX-XX-XX" autocomplete="off" value="'+esc(L.phone)+'"></div></div><button class="btn primary" id="lgo" data-act="lcode" '+(L.phone.replace(/\D/g,'').length>=11?'':'disabled')+'>Получить код</button><button class="btn outline" data-act="lstart">Назад</button>'+dchips('Демо-данные',[['Подставить номер','l:phone'],['Короткий номер','l:short']])}
 else if(L.step==='code'){b='<h3>Код из Telegram</h3><div class="fld"><span class="lbl2">Мы отправили код в Telegram на номер '+esc(L.phone)+'</span><div class="code'+(L.err?' bad':'')+'">'+[0,1,2,3,4,5].map(function(i){return '<input data-code="'+i+'" inputmode="numeric" maxlength="1" aria-label="Цифра '+(i+1)+'" autocomplete="one-time-code">'}).join('')+'</div>'+(L.err?'<div class="hint bad">Неверный или просроченный код</div>':'<div class="hint">Для проверки введите любые 6 цифр, кроме 000000</div>')+'</div><button class="btn primary" data-act="lcheck">Войти</button><div class="hint" id="resend">'+resendText(L)+'</div><button class="btn soft" id="rbtn" data-act="lresend" '+(L.resend>0?'disabled':'')+'>'+ic('redo',16)+'Отправить код повторно</button>'+dchips('Демо-данные',[['Верный код','l:codeok'],['Неверный код','l:codebad']])}
 else{b='<h3>Завершение регистрации</h3><p>Введите реальные данные: они нужны для проверки транзакций (KYC).</p><div class="fld"><label class="lbl2" for="lfio">Фамилия Имя Отчество</label><div class="inp"><input id="lfio" data-bind="lfio" placeholder="Сидоров Иван Иванович" autocomplete="off" value="'+esc(L.fio)+'"></div></div><div class="fld"><label class="lbl2" for="lem">Электронная почта</label><div class="inp"><input id="lem" data-bind="lem" type="email" placeholder="ivan@libre.zone" autocomplete="off" value="'+esc(L.email)+'"></div></div><button class="btn primary" id="lfin" data-act="lfinish" '+(regOk(L)?'':'disabled')+'>Завершить регистрацию</button>'+dchips('Демо-данные',[['Заполнить','l:regok'],['Некорректные данные','l:regbad']])}
 return b}
function loginHTML(){return '<div class="scrim end" data-act="lclose"><div class="sheet" role="dialog" aria-modal="true" aria-label="Вход"><div class="grab"></div><div class="sh"><div class="logo" style="margin:8px 0 4px">'+logoMark()+'<span>Libre<b>.zone</b></span></div><button class="xbtn2" data-act="lclose" aria-label="Закрыть">'+ic('close',20)+'</button></div><div class="modal" style="margin:0;padding:0;box-shadow:none;background:none;overflow:visible">'+loginBody()+'</div></div></div>'}

